7: function flyctlBin() {
8:   const local = path.join(os.homedir(), '.fly', 'bin', process.platform === 'win32' ? 'flyctl.exe' : 'flyctl');
9:   return fs.existsSync(local) ? local : 'flyctl'; // fall back to PATH
