16: function run(args, token, { capture = false, cwd } = {}) {
17:   const r = spawnSync(flyctlBin(), args, {
18:     env: flyEnv(token),
19:     cwd,
20:     stdio: capture ? ['ignore', 'pipe', 'pipe'] : 'inherit',
21:     encoding: 'utf8',
22:   });
23:   if (r.error && r.error.code === 'ENOENT') {
24:     throw new Error('flyctl not installed — https://fly.io/docs/flyctl/install/');
25:   }
26:   return r;
27: }
