38:   const r = run(
39:     ['deploy', '.', '--app', flyApp, '--config', '.small/fly.toml', '--dockerfile', '.small/Dockerfile', '--remote-only', '--ha=false', '--yes'],
40:     token,
41:     { cwd }
42:   );
43:   if (r.status !== 0) throw new Error('deploy failed — see flyctl output above');
44: }
