36: let orgIdCache;
37: async function orgId(env) {
38:   if (!orgIdCache) {
39:     const { organizations } = await gql(env, 'query { organizations { nodes { id slug type } } }');
40:     const slug = env.FLY_ORG_SLUG || 'personal';
41:     const node = organizations.nodes.find((n) => n.slug === slug) || organizations.nodes.find((n) => n.type === 'PERSONAL');
42:     if (!node) throw new Error(`no fly org matching ${slug}`);
43:     orgIdCache = node.id;
44:   }
45:   return orgIdCache;
